SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"019f9ebf-c0d6-7cce-92bf-0d30400cfc26","topic_id":"019f9df7-a2a2-7865-ab8c-df9bc214c173","prompt":"A function is given by s = (r - 3q) / q^2. Evaluate s when q = -3 and r = 5.","model_answer":"14/9","explanation":"Substitute q = -3 and r = 5 into s = (r - 3q) / q^2. Then s = (5 - 3(-3)) / (-3)^2 = 14/9.","difficulty":"Easy","metadata":{"tags":"functions,substitution,algebra","subtopic":"substitution","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.710Z","updated_at":"2026-07-26T14:06:34.710Z"},{"id":"01a00459-8b88-7aec-a320-05e9aeda492f","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"The universal set contains the integers from 1 to 15. Set A contains the perfect squares and set B contains the prime numbers. Find n(A ∪ B).","model_answer":"9","explanation":"A = {1, 4, 9}. B = {2, 3, 5, 7, 11, 13}. There is no overlap, so n(A ∪ B) = 3 + 6 = 9.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.424Z","updated_at":"2026-08-15T07:36:12.424Z"},{"id":"01a00459-8b9c-7a18-81ec-2dd7d0fc76a3","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"The universal set contains the integers from 1 to 15. Set B contains the prime numbers. List the elements of B''.","model_answer":"{1, 4, 6, 8, 9, 10, 12, 14, 15}","explanation":"The primes from 1 to 15 are 2, 3, 5, 7, 11 and 13. The complement B'' contains all other integers in the universal set.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.444Z","updated_at":"2026-08-15T07:36:12.444Z"},{"id":"019f9ebf-c10b-7e4a-a312-9bdad7d859f3","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A shop sells watches at $210 each. Jimmy buys them at a 20% discount and then sells them at a 20% profit with a 10% discount on the marked price. Find the marked price.","model_answer":"$224","explanation":"Jimmy''s cost price is 80% of 210, so it is 168. To make a 20% profit, he needs to sell at 201.60. If this is after a 10% discount, then the marked price is 201.60 ÷ 0.9 = 224.","difficulty":"Medium","metadata":{"tags":"percentages,profit-and-loss,discount","subtopic":"profit and discount","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.763Z","updated_at":"2026-07-26T14:06:34.763Z"},{"id":"019f9ebf-c10f-7fcc-8d04-77445751fea6","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"A student walks 1000 metres at 4 km/h, takes a 5 minute break, then runs 1.3 km in 5 minutes. Will the whole exercise be completed by 09:30 if the student starts at 08:50?","model_answer":"Yes","explanation":"Walking 1000 m at 4 km/h takes 15 minutes. Add the 5 minute break and 5 minutes running for a total of 25 minutes. Starting at 08:50 means the student finishes at 09:15, which is before 09:30.","difficulty":"Easy","metadata":{"tags":"numbers,time,speed","subtopic":"time and speed","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.767Z","updated_at":"2026-07-26T14:06:34.767Z"},{"id":"019f9e72-b6c8-7467-94c3-4dc43c0fbd39","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Find the first negative term of the sequence whose nth term is 87 - 9n.","model_answer":"The 10th term (-3)","explanation":"Solve 87 - 9n < 0. Then 9n > 87, so n > 9.666... The smallest integer n is 10. The 10th term is 87 - 90 = -3.","difficulty":"Medium","metadata":{"tags":"algebra,sequences,inequalities","subtopic":"sequence inequalities","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.864Z","updated_at":"2026-07-26T12:42:25.864Z"},{"id":"019f9ebf-c0f9-7dd7-b923-9fb7158d1938","topic_id":"019f9df7-a2a2-78ab-b1d6-52be9d287151","prompt":"ABC is part of a polygon and the interior angle at A is 148°. The remaining interior angles are each 139°. Find the number of sides of the polygon.","model_answer":"9","explanation":"Let the polygon have n sides. One interior angle is 148° and the other (n − 1) interior angles are each 139°. So 148 + (n − 1) × 139 = (n − 2) × 180. Solving gives n = 9.","difficulty":"Medium","metadata":{"tags":"angles,polygons,interior-angles","subtopic":"polygons","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T14:06:34.745Z","updated_at":"2026-07-26T14:06:34.745Z"},{"id":"019fa42c-3501-7dcf-ba5e-66f75d786ca0","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Expand and simplify the expression (4x - 3)(5 + 2x) - (3x - 1)^2.","model_answer":"-x^2 + 20x - 16","explanation":"(4x - 3)(5 + 2x) = 20x + 8x^2 - 15 - 6x = 8x^2 + 14x - 15.\n(3x - 1)^2 = 9x^2 - 6x + 1.\nSubtracting gives: (8x^2 + 14x - 15) - (9x^2 - 6x + 1) = -x^2 + 20x - 16.","difficulty":"Medium","metadata":{"tags":"algebra,expansion","subtopic":"expansion","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-27T15:23:08.417Z","updated_at":"2026-07-27T15:23:08.417Z"},{"id":"019fa42c-3506-742e-b0e4-dfa63c5814a4","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"(a) Express 3150 as a product of its prime factors in index notation.\n(b) Given that 1260 = 2^2 × 3^2 × 5 × 7, find:\n(i) the highest common factor (HCF) of 3150 and 1260,\n(ii) the smallest positive integer k such that 3150k is a perfect cube.","model_answer":"(a) 2 × 3^2 × 5^2 × 7\n(b)(i) 630\n(b)(ii) 2940","explanation":"(a) Prime factorisation of 3150 = 2 × 3^2 × 5^2 × 7.\n(b)(i) HCF = 2^1 × 3^2 × 5^1 × 7^1 = 630.\n(b)(ii) For 3150k to be a perfect cube, powers of prime factors must be multiples of 3.\nk = 2^(3-1) × 3^(3-2) × 5^(3-2) × 7^(3-1) = 2^2 × 3^1 × 5^1 × 7^2 = 4 × 3 × 5 × 49 = 2940.","difficulty":"Hard","metadata":{"tags":"HCF,LCM,prime factors","subtopic":"prime factorisation","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-27T15:23:08.422Z","updated_at":"2026-07-27T15:23:08.422Z"},{"id":"019fa42c-350a-7fe3-ba72-d7e208575c05","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"It is given that y = \\sqrt{\\frac{5x}{3x + 4z}}.\n(a) Calculate the value of y when x = 4 and z = 3.5.\n(b) Express x in terms of y and z.","model_answer":"(a) 0.877\n(b) x = (4z y^2) / (5 - 3y^2)","explanation":"(a) y = sqrt(20 / (12 + 14)) = sqrt(20/26) ≈ 0.877 (3 s.f.).\n(b) Square both sides: y^2 = 5x / (3x + 4z).\n3x y^2 + 4z y^2 = 5x.\n4z y^2 = 5x - 3x y^2 = x(5 - 3y^2).\nx = (4z y^2) / (5 - 3y^2).","difficulty":"Medium","metadata":{"tags":"formulae,rearranging","subtopic":"changing subject","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-27T15:23:08.426Z","updated_at":"2026-07-27T15:23:08.426Z"},{"id":"019fa42c-3514-7687-939c-e809ec8ecb21","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Solve the equation \\frac{x + 2}{x - 1} - \\frac{x - 3}{x + 3} = 3, giving your answers correct to 2 decimal places.","model_answer":"x = 2.56 or x = -1.56","explanation":"[(x+2)(x+3) - (x-3)(x-1)] / [(x-1)(x+3)] = 3\n(x^2 + 5x + 6 - (x^2 - 4x + 3)) / (x^2 + 2x - 3) = 3\n(9x + 3) = 3(x^2 + 2x - 3)\n9x + 3 = 3x^2 + 6x - 9\n3x^2 - 3x - 12 = 0\nx^2 - x - 4 = 0\nUsing quadratic formula: x = [1 ± sqrt(1 - 4(1)(-4))] / 2 = [1 ± sqrt(17)] / 2\nx ≈ 2.56 or x ≈ -1.56.","difficulty":"Hard","metadata":{"tags":"algebraic fractions,equations","subtopic":"algebraic fractions","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-27T15:23:08.436Z","updated_at":"2026-07-27T15:23:08.436Z"},{"id":"019fa42c-3519-7299-b589-8853125f9320","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"In 2023, a motor company produced 4 620 000 hybrid vehicles.\n(a) Express 4 620 000 in standard form.\n(b) In 2018, the company produced 3.25 million hybrid vehicles. Calculate the percentage increase in hybrid vehicle production from 2018 to 2023.\n(c) In 2023, 78.5% of all motor vehicles produced by the company were non-hybrid vehicles. Calculate the total number of motor vehicles produced by the company in 2023, giving your answer to the nearest million.\n(d) Given that there were 350 vehicles produced per 1000 people in the region in 2023, estimate the total population of the region in standard form correct to 3 significant figures.","model_answer":"(a) 4.62 × 10^6\n(b) 42.2%\n(c) 21 million\n(d) 6.14 × 10^7","explanation":"(a) 4 620 000 = 4.62 × 10^6.\n(b) Percentage increase = [(4.62 - 3.25) / 3.25] × 100% = 42.15% ≈ 42.2%.\n(c) Hybrid percentage = 100% - 78.5% = 21.5%.\nTotal vehicles = 4,620,000 / 0.215 = 21,488,372 ≈ 21 million.\n(d) Population = (21,488,372 / 350) × 1000 = 61,395,348 ≈ 6.14 × 10^7.","difficulty":"Hard","metadata":{"tags":"percentages,standard form","subtopic":"percentages","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-27T15:23:08.441Z","updated_at":"2026-07-27T15:23:08.441Z"},{"id":"019fa42c-351d-7bfa-bdd5-0ac062b11d83","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A scale model of a water reservoir dam is constructed such that an actual length of 1800 m is represented by 45 cm on the model.\n(a) Express the scale of the model in the form 1 : n.\n(b) The surface area of the reservoir on the scale model is 0.24 m^2. Calculate the actual surface area of the reservoir in square kilometres.","model_answer":"(a) 1 : 4000\n(b) 3.84 km^2","explanation":"(a) 45 cm : 1800 m = 45 cm : 180,000 cm = 1 : 4000.\n(b) 1 m on model represents 4000 m = 4 km in actual distance.\nArea ratio: 1 m^2 : (4 km)^2 = 1 m^2 : 16 km^2.\nActual surface area = 0.24 × 16 = 3.84 km^2.","difficulty":"Medium","metadata":{"tags":"scale,ratio,area","subtopic":"scale","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-27T15:23:08.445Z","updated_at":"2026-07-27T15:23:08.445Z"},{"id":"019fa42c-352e-7aab-a740-ebe0b122792f","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"(a) Solve the linear equation 5(2x - 3) - 4(x + 2) = 3(4x + 1) - 10.\n(b) Solve the inequality \\frac{3 - 2x}{4} \\ge 2 - \\frac{x + 1}{3}.","model_answer":"(a) x = -8/3 (or -2 2/3)\n(b) x <= -5.5","explanation":"(a) Expand: 10x - 15 - 4x - 8 = 12x + 3 - 10\n6x - 23 = 12x - 7\n-6x = 16 => x = -16/6 = -8/3.\n(b) Multiply by 12: 3(3 - 2x) ≥ 24 - 4(x + 1)\n9 - 6x ≥ 24 - 4x - 4\n9 - 6x ≥ 20 - 4x\n-2x ≥ 11 => x ≤ -5.5.","difficulty":"Medium","metadata":{"tags":"equations,inequalities","subtopic":"inequalities","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-27T15:23:08.462Z","updated_at":"2026-07-27T15:23:08.462Z"},{"id":"019fa42c-3539-72ee-bb1a-0117f6884016","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve the simultaneous equations:\n3x - 2y = -12\n4x + 5y = 7","model_answer":"x = -2, y = 3","explanation":"Multiply 3x - 2y = -12 by 5: 15x - 10y = -60.\nMultiply 4x + 5y = 7 by 2: 8x + 10y = 14.\nAdd the two equations: 23x = -46 => x = -2.\nSubstitute x = -2 into 3x - 2y = -12:\n3(-2) - 2y = -12 => -6 - 2y = -12 => 2y = 6 => y = 3.","difficulty":"Medium","metadata":{"tags":"simultaneous equations","subtopic":"simultaneous equations","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-27T15:23:08.473Z","updated_at":"2026-07-27T15:23:08.473Z"}]'::json)
