SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"01a00459-8c8d-7444-b13b-5bf17fee9465","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Simplify (p - 3n)(4n - 1) / [12n(4n - 1)].","model_answer":"(3n - p)/(12n)","explanation":"Cancel the common factor (4n - 1) from numerator and denominator. Since p - 3n = -(3n - p), the expression becomes (3n - p)/(12n).","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.685Z","updated_at":"2026-08-15T07:36:12.685Z"},{"id":"01a00459-8ca2-7a4a-a146-58df5bcef9cb","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"The green and red lights flash every 6 seconds and 8 seconds respectively. If they start together, how long will it take for them to next flash simultaneously?","model_answer":"24 s","explanation":"Find the least common multiple of 6 and 8. LCM(6, 8) = 24, so they will next flash together after 24 seconds.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.706Z","updated_at":"2026-08-15T07:36:12.706Z"},{"id":"01a00459-8cb6-7d56-8d02-0771e5f0e07f","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"Express 2250 as a product of its prime factors.","model_answer":"2 × 3^2 × 5^3","explanation":"2250 = 225 × 10 = (3^2 × 5^2) × (2 × 5) = 2 × 3^2 × 5^3.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.726Z","updated_at":"2026-08-15T07:36:12.726Z"},{"id":"01a00459-8cc8-7b7c-ae66-f21a57028440","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"The period P of a pendulum is directly proportional to the square root of its length L. If P increases by 25%, what is the percentage increase in L?","model_answer":"56.25%","explanation":"Since P is proportional to sqrt(L), L is proportional to P^2. If P increases by 25%, then L changes by 1.25^2 = 1.5625. So the increase in L is 56.25%.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.744Z","updated_at":"2026-08-15T07:36:12.744Z"},{"id":"01a00459-8cde-7bf9-a539-db60dc46ab03","topic_id":"019f9df7-a2a2-78ab-b1d6-52be9d287151","prompt":"The Great Pyramid has surface area 8.30 × 10^4 m^2 and volume 2.45 × 10^4 m^3. A similar replica has volume 9.22 × 10^-6 m^3. Estimate the surface area of the replica.","model_answer":"4.33 × 10^-2 m^2","explanation":"For similar solids, surface area scales with the square of the linear scale and volume scales with the cube. Use the volume ratio to find the linear scale, then square it and apply it to 8.30 × 10^4. This gives approximately 4.33 × 10^-2 m^2.","difficulty":"Hard","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.766Z","updated_at":"2026-08-15T07:36:12.766Z"},{"id":"01a00459-8d04-7ab9-a66a-cc53880b1cdb","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"The universal set is the integers from 0 to 10. Set A = {1, 4, 9} and set B = {1, 2, 4, 8}. Describe the elements of set A.","model_answer":"Perfect squares","explanation":"The elements 1, 4 and 9 are the perfect squares in the universal set from 0 to 10.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.804Z","updated_at":"2026-08-15T07:36:12.804Z"},{"id":"01a00459-8d09-7d55-b50a-8fa02ef5fae0","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Find the number of elements in A ∪ B, where A = {1, 4, 9} and B = {1, 2, 4, 8}.","model_answer":"5","explanation":"A ∪ B = {1, 2, 4, 8, 9}. There are 5 elements in the union.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.809Z","updated_at":"2026-08-15T07:36:12.809Z"},{"id":"01a00459-8d18-7bab-b5b9-15e664401ba9","topic_id":"019f9df7-a2a2-78c7-aa4b-565799c65ce4","prompt":"A function is given by s = (r - 3q) / q^2. Evaluate s when q = -3 and r = 5.","model_answer":"14/9","explanation":"Substitute q = -3 and r = 5 into s = (r - 3q) / q^2. Then s = (5 - 3(-3)) / (-3)^2 = 14/9.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.824Z","updated_at":"2026-08-15T07:36:12.824Z"},{"id":"01a00459-8d40-79b4-9dae-8b2e881edaba","topic_id":"019f9df7-a2a2-78da-b367-27466579928e","prompt":"Solve the inequality (2x + 1)/3 >= (3x - 1)/5.","model_answer":"x >= -8","explanation":"Multiply both sides by 15: 5(2x + 1) >= 3(3x - 1). Expand: 10x + 5 >= 9x - 3. Subtract 9x: x + 5 >= -3. Subtract 5: x >= -8.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.864Z","updated_at":"2026-08-15T07:36:12.864Z"},{"id":"01a00459-8d57-7d13-bc0c-3d0c1a2d1d7f","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"A shop sells watches at $210 each. Jimmy buys them at a 20% discount and then sells them at a 20% profit with a 10% discount on the marked price. Find the marked price.","model_answer":"$224","explanation":"Jimmy''s cost price is 80% of 210, so it is 168. To make a 20% profit, he needs to sell at 201.60. If this is after a 10% discount, then the marked price is 201.60 ÷ 0.9 = 224.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.887Z","updated_at":"2026-08-15T07:36:12.887Z"},{"id":"01a00459-8d6a-75d6-b7fa-f880bb491ff9","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A student walks 1000 metres at 4 km/h, takes a 5 minute break, then runs 1.3 km in 5 minutes. Will the whole exercise be completed by 09:30 if the student starts at 08:50?","model_answer":"Yes","explanation":"Walking 1000 m at 4 km/h takes 15 minutes. Add the 5 minute break and 5 minutes running for a total of 25 minutes. Starting at 08:50 means the student finishes at 09:15, which is before 09:30.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.906Z","updated_at":"2026-08-15T07:36:12.906Z"},{"id":"01a00459-8d6f-7941-a2ab-867817a513c4","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Find the first negative term of the sequence whose nth term is 87 - 9n.","model_answer":"The 10th term (-3)","explanation":"Solve 87 - 9n < 0. Then 9n > 87, so n > 9.666... The smallest integer n is 10. The 10th term is 87 - 90 = -3.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.911Z","updated_at":"2026-08-15T07:36:12.911Z"},{"id":"01a00459-8da4-7b3d-ba33-1c7d52395891","topic_id":"019f9df7-a2a2-7865-ab8c-df9bc214c173","prompt":"ABC is part of a polygon and the interior angle at A is 148°. The remaining interior angles are each 139°. Find the number of sides of the polygon.","model_answer":"9","explanation":"Let the polygon have n sides. One interior angle is 148° and the other (n − 1) interior angles are each 139°. So 148 + (n − 1) × 139 = (n − 2) × 180. Solving gives n = 9.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.964Z","updated_at":"2026-08-15T07:36:12.964Z"},{"id":"01a00459-8daa-7a0c-986a-9f06c4cafb82","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Expand and simplify the expression (4x - 3)(5 + 2x) - (3x - 1)^2.","model_answer":"-x^2 + 20x - 16","explanation":"(4x - 3)(5 + 2x) = 20x + 8x^2 - 15 - 6x = 8x^2 + 14x - 15. (3x - 1)^2 = 9x^2 - 6x + 1. Subtracting gives: (8x^2 + 14x - 15) - (9x^2 - 6x + 1) = -x^2 + 20x - 16.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.970Z","updated_at":"2026-08-15T07:36:12.970Z"},{"id":"01a00459-8dcc-7c45-aed0-1fca2b78ef7b","topic_id":"019f9df7-a2a2-78da-b367-27466579928e","prompt":"Solve the equation 3x/(2-x) - 5/(x+4) = 3, giving your answers correct to 3 significant figures.","model_answer":"x = 1.14 or x = -4.97","explanation":"1. Combine fractions on the left-hand side: [3x(x+4) - 5(2-x)] / [(2-x)(x+4)] = 3.\n2. Simplify numerator: 3x^2 + 12x - 10 + 5x = 3x^2 + 17x - 10.\n3. Multiply by denominator: 3x^2 + 17x - 10 = 3(-x^2 - 2x + 8).\n4. Expand and rearrange into standard quadratic form: 6x^2 + 23x - 34 = 0.\n5. Use quadratic formula: x = (-23 ± √(23^2 - 4(6)(-34)))/(2(6)) = (-23 ± √1345)/12.\n6. x ≈ 1.14 or x ≈ -4.97.","difficulty":"Hard","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:13.004Z","updated_at":"2026-08-15T07:36:13.004Z"}]'::json)
